export function legacyAnimationsDisabled(): boolean {
    try {
        assertInInjectionContext(legacyAnimationsDisabled);
    }
    catch {
        return false;
    }
    return getLegacyAnimationsState() !== 'enabled';
}

constructor(
@Optional()
@Inject(ANIMATION_MODULE_TYPE)
public _animationMode?: string) {
    let inContext = true;
    try {
        assertInInjectionContext(MatLegacyPseudoCheckbox);
    }
    catch {
        inContext = false;
    }
    this._diAnimationsDisabled = inContext ? legacyAnimationsDisabled() : false;
}

function dialogAnimationsDisabled(): boolean {
    try {
        assertInInjectionContext(dialogAnimationsDisabled);
    }
    catch {
        return false;
    }
    return legacyAnimationsDisabled();
}

function ambientService<T>(token: ProviderToken<T>): T | null {
    try {
        assertInInjectionContext(ambientService);
    }
    catch {
        return null;
    }
    return inject(token, { optional: true });
}

